import React, { useEffect, useState } from "react";
import PrescriptionOrdersTable from "./PrescriptionOrdersTable";

import useApi from "../../../hooks/useApi";
import { useNavigate, useParams } from "react-router-dom";
import departmentsApi from "../../../api/departmentsApi";
import { Loading } from "../../../components";
import { useStateContext } from "../../../contexts/ContextProvider";
import hospitalsApi from "../../../api/hospitals/hospitalsApi";

const columns = [
  { name: "Client", uid: "dependant_name" },
  { name: "Reference", uid: "reference_number" },
  { name: "Status", uid: "status" },
  { name: "Amount", uid: "order_total_price" },
  { name: "Paid", uid: "is_paid" },
  { name: "Date", uid: "created" },
  { name: "Actions", uid: "actions" },
];

function PrescriptionOrdersList() {
  const [openDepartmentFormModal, setopenDepartmentFormModal] = useState(false);
  const [user, setUser] = useState();
  const navigate = useNavigate();
  const [selectedDepartment, setselectedDepartment] = useState();
  const [prescriptionOrders, setprescriptionOrders] = useState([]);
  const [data, setdata] = useState([]);
  const [modalTitle, setmodalTitle] = useState("");
  const [updated, setUpdated] = useState(false);

  const getPrescriptionOrdersActionsApi = useApi(hospitalsApi.hospitalStaffAction);

  const { loggedInUser } = useStateContext();

  const getPrescriptionOrders = async (data) => {
    console.log("idee", data);
    await getPrescriptionOrdersActionsApi.request({
      action: "GetUserPrescriptionOrders",
     
    });
  };

  useEffect(() => {
    if (getPrescriptionOrdersActionsApi.data) {
      if (getPrescriptionOrdersActionsApi.data.length) {
        setprescriptionOrders(getPrescriptionOrdersActionsApi.data);
      }
    }
  }, [getPrescriptionOrdersActionsApi.data]);

  useEffect(() => {
    if (loggedInUser !== null && loggedInUser.entity_id !== null) {
      getPrescriptionOrders(loggedInUser.entity_id);
    }
    console.log("loggedInUser", loggedInUser);
  }, []);

  useEffect(() => {
    setdata(prescriptionOrders);
  }, [prescriptionOrders]);

  const handleEditAction = (item) => {
    setopenDepartmentFormModal(true);
    setselectedDepartment(item);
    setmodalTitle(`Edit ${item.tittle}`);
  };

  const handleAddAction = () => {
    setopenDepartmentFormModal(true);
    setmodalTitle("Add new body system");
    setselectedDepartment(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/systems/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/systems/delete/${item.id}`);
  };

  useEffect(() => {
    if (getPrescriptionOrdersActionsApi.data && getPrescriptionOrdersActionsApi.data.length) {
      setprescriptionOrders(getPrescriptionOrdersActionsApi.data);
    }
    console.log("getDepartmentsActionsApi.data", getPrescriptionOrdersActionsApi.data);
  }, [getPrescriptionOrdersActionsApi.data]);

  useEffect(() => {
    if (updated === true) {
      if (loggedInUser !== null && loggedInUser.entity_id !== null) {
        getPrescriptionOrders(loggedInUser.entity_id);
      }
    }
  }, [updated]);

  //Filtering data
  useEffect(() => {
    setdata(prescriptionOrders);
  }, [prescriptionOrders]);

  const handleFilter = (e) => {
    const search_param = e;
    if (
      prescriptionOrders &&
      prescriptionOrders.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        prescriptionOrders.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(prescriptionOrders);
    }
  };

  return getPrescriptionOrdersActionsApi.loading ? (
    <Loading loading={departmentsApi.loading} />
  ) : (
    <div className="mt-16 md:mt-2">

      <PrescriptionOrdersTable
      title={"Prescription Orders"}
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>
  );
}

export default PrescriptionOrdersList;
